select count(*) as jra_preflights,count(*) filter(where p.id is not null) as linked_frozen,count(*) filter(where j.id is not null) as linked_job,count(*) filter(where j.job_status='DONE') as linked_done,count(*) filter(where s.captured_at<s.post_time-interval '3 minutes') as prestart3_capture from private.lab_rank_shadow_preflight_v1 s left join public.official_predictions p on (p.race_date,p.track,p.race_no,p.circuit)=(s.race_date,s.track,s.race_no,'JRA') and p.status='FROZEN' left join public.jra_prediction_jobs j on j.id=s.job_id where s.circuit='JRA' and s.race_date between '2026-10-17' and '2026-11-15';
